mod tests2 {
    use super::*;
    use nix::sys::mman::{munmap, MapFlags, ProtFlags};

    #[test]
    fn test_aligned_mem() {
        let kb: usize = 1024;
        let mb: usize = 1024 * kb;

        struct TestProps {
            pub mem_size: usize,
            pub mem_align: usize,
            pub offset: usize,
        };

        let tests = vec![
            TestProps {
                mem_size: 1 * mb,
                mem_align: 1 * mb,
                offset: 0,
            },
            TestProps {
                mem_size: 1 * mb,
                mem_align: 2 * mb,
                offset: 0,
            },
            TestProps {
                mem_size: 32 * mb,
                mem_align: 32 * mb,
                offset: 0,
            },
            TestProps {
                mem_size: 32 * mb,
                mem_align: 32 * mb,
                offset: 4 * kb,
            },
        ];

        for test in tests {
            let mem = unsafe {
                mmap_aligned(
                    test.mem_size,
                    ProtFlags::PROT_READ | ProtFlags::PROT_WRITE,
                    MapFlags::MAP_ANON | MapFlags::MAP_PRIVATE,
                    test.mem_align,
