///     // Error (if any) will be sent to the event loop (see `wait_for_event`).
///     // In this case, the cookie can be discarded.
///     conn.send_request(&x::CreateWindow {
///         depth: x::COPY_FROM_PARENT as u8,
///         wid: window,
///         parent: screen.root(),
