                continue;
            }
            if sent != 0 {
                // We need to report that some packets were sent in this case, so we rely on
                // errors being either harmlessly transient (in the case of WouldBlock) or
                // recurring on the next call.
                return Ok(sent);
            }
            return Err(e);
        } else {
            sent += 1;
        }
    }
