#[macro_export]
macro_rules! project_struct {
    ($struct:ident: $ty:path => $field:tt) => {
        #[allow(unused_unsafe)]
        (unsafe {
            &mut *($struct as &mut MaybeUninit<$ty>)
                .as_mut_ptr()
                .cast::<u8>()
                .add($crate::offset_of!($ty, $field))
                .cast()
        })
    };
    ($struct:ident: $struct_ty:path => $field:tt: $field_ty:path) => {
        #[allow(unused_unsafe)]
        (unsafe {
            &mut *($struct as &mut MaybeUninit<$struct_ty>)
                .as_mut_ptr()
                .cast::<u8>()
                .add($crate::offset_of!($struct_ty, $field))
                .cast::<MaybeUninit<$field_ty>>()
        })
    };
}

#[macro_export]
macro_rules! project_tuple {
    ($tuple:ident: $ty:path => $index:tt) => {
        (unsafe {
            &mut *($tuple as &mut MaybeUninit<$ty>)
                .as_mut_ptr()
                .cast::<u8>()
                .add(memoffset::offset_of_tuple!($ty, $index))
                .cast()
        })
    };
    ($tuple:ident: $tuple_ty:path => $index:tt: $index_ty:path) => {
        (unsafe {
            &mut *($tuple as &mut MaybeUninit<$tuple_ty>)
                .as_mut_ptr()
                .cast::<u8>()
                .add(memoffset::offset_of_tuple!($tuple_ty, $index))
                .cast::<MaybeUninit<$index_ty>>()
        })
    };
}

#[macro_export]
macro_rules! resolve_struct {
    ($out:ident = |$pos:ident, $resolver:ident| -> $out_ty:path { $($field:ident: $field_expr:expr),* }) => {
        resolve_struct!($out = |$pos, $resolver| -> $out_ty { $($field: $field_expr,)* });
    };
    ($out:ident = |$pos:ident, $resolver:ident| -> $out_ty:path { $($field:ident: $field_expr:expr,)* }) => {
        $(
            unsafe {
                let field_offset = memoffset::offset_of!($out_ty, $field);
                $field_expr.resolve(
                    $pos + field_offset,
                    $resolver.$field,
                    &mut *$out.as_mut_ptr().cast::<u8>().add(field_offset).cast()
                );
            }
        )*
    };
}

    }
}

impl<T, const R: usize, const C: usize> SMatrix<T, R, C> {
    /// Creates a new statically-allocated matrix from the given [ArrayStorage].
    ///
    /// This method exists primarily as a workaround for the fact that `from_data` can not
    /// work in `const fn` contexts.
    #[inline(always)]
    pub const fn from_array_storage(storage: ArrayStorage<T, R, C>) -> Self {
        // This is sound because the row and column types are exactly the same as that of the
        // storage, so there can be no mismatch
        unsafe { Self::from_data_statically_unchecked(storage) }
    }
}

